<?php
namespace App\Http\Middleware;use Closure;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Symfony\Component\HttpFoundation\Response;
class IntegrationApiAuth{public function handle(Request$r,Closure$next):Response{$plain=$r->bearerToken();if(!$plain)return response()->json(['success'=>false,'message'=>'Token API requerido'],401);$token=DB::table('integration_api_tokens')->where(['token_hash'=>hash('sha256',$plain),'status'=>'active'])->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->first();if(!$token)return response()->json(['success'=>false,'message'=>'Token API inválido o vencido'],401);$abilities=json_decode($token->abilities?:'[]',true);$needed=$r->isMethod('GET')?'read':'write';if(!in_array($needed,$abilities)&&!in_array('*',$abilities))return response()->json(['success'=>false,'message'=>'El token no tiene permiso '.$needed],403);DB::table('integration_api_tokens')->where('id',$token->id)->update(['last_used_at'=>now(),'updated_at'=>now()]);$r->attributes->set('integration_company_id',$token->company_id);$r->attributes->set('integration_token_id',$token->id);return$next($r);}}
